templateFn:
const categories = (params.categories || []).join(", ");
  return `Classify the following user message into exactly one of these categories: ${categories}

User message: "${params.message}"

Respond with a JSON object containing "intent" (the matching category) and "confidence" (0-1).`;

return `Analyze the following message and determine if it's a query (read operation) or transaction (mutation/write operation):

  A query is any operation that reads or retrieves data without modifying it.
  A transaction is any operation that creates, updates, or deletes data.

  <queryExamples>
  ${params.queryExamples}
  </queryExamples>

  <transactionExamples>
  ${params.transactionExamples}
  </transactionExamples>

  Message: "${params.dbPrompt}"

  Please classify the message as either a query or a transaction.`;

return `
<examples>
${params.selectedDoc}
</examples>

Use the provided examples to write the code to satisfy the user message. Only respond with code (no codeblock backticks).`;

const maxSentences = params.maxSentences || 3;
  return `Summarize the following text in ${maxSentences} sentence(s) or fewer.

Text:
${params.text}`;
